package com.nexusdrive.auth.config; import com.nexusdrive.common.config.JwtProperties;import com.nexusdrive.common.security.*;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; @Configuration @EnableMethodSecurity public class SecurityConfig {@Bean JwtTokenProvider jwtTokenProvider(JwtProperties p){return new JwtTokenProvider(p);}@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}@Bean JwtAuthFilter jwtAuthFilter(JwtTokenProvider j){return new JwtAuthFilter(j);}@Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}}
